#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
export PATH="$(lean --print-prefix)/bin:$PATH"
# Exports must first be generated by scripts/export_comparator.py.
# This verifies exported proof terms; it does not sandbox their source build.
lake comparator --config comparator.json \
  --challenge-from-export .lake/final-exports/challenge.ndjson \
  --solution-from-export .lake/final-exports/solution.ndjson \
  --inadvisably-no-sandbox
